python
def switchboardRingsPositiveInkInvoice(links, k):
    a=links
    out=[]
    from collections import deque
    n=len(a)
    dist=[-1]*n
    queue=deque()
    if n:
        dist[0]=0
        queue.append(0)
    while queue:
        u=queue.popleft()
        for v in range(n):
            if a[u][v] and dist[v]==-1:
                dist[v]=dist[u]+1
                queue.append(v)
    out=dist
    return sum(x for x in out if x>0)


java
class Solution {
  public int switchboardRingsPositiveInkInvoice(int[][] links, int k) {
    int[][] a=links; List<Integer> out=new ArrayList<>();
    {int n=a.length;int[]dist=new int[n];Arrays.fill(dist,-1);Deque<Integer>queue=new ArrayDeque<>();if(n>0){dist[0]=0;queue.add(0);}while(!queue.isEmpty()){int u=queue.remove();for(int v=0;v<n;v++)if(a[u][v]!=0&&dist[v]==-1){dist[v]=dist[u]+1;queue.add(v);}}for(int d:dist)out.add(d);}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
